public static void validateBootstrapConfig(Kernel.BootstrapConfig msg) throws ProtoException {
if (msg == null) {
return;
}
// Validate clusterName (assert_required)
if (msg.getClusterName().isEmpty()) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,"field clusterName is required");
}
// Validate nodeCount (assert_gt: 0)
if (msg.getNodeCount() <= 0) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field nodeCount must be > 0, got: %s", msg.getNodeCount()));
}
// Validate partitionCount (assert_gt: 0)
if (msg.getPartitionCount() <= 0) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field partitionCount must be > 0, got: %s", msg.getPartitionCount()));
}
}
