public static void validateConfig(Kernel.Config msg) throws ProtoException {
if (msg == null) {
return;
}
// Validate caCertLifetimeSeconds (assert_duration: POSITIVE)
if (msg.getCaCertLifetimeSeconds() <= 0) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field caCertLifetimeSeconds must be positive (> 0), got: %d", msg.getCaCertLifetimeSeconds()));
}
// Validate accessTokenLifetimeSeconds (assert_duration: POSITIVE)
if (msg.getAccessTokenLifetimeSeconds() <= 0) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field accessTokenLifetimeSeconds must be positive (> 0), got: %d", msg.getAccessTokenLifetimeSeconds()));
}
// Validate refreshTokenLifetimeSeconds (assert_duration: POSITIVE)
if (msg.getRefreshTokenLifetimeSeconds() <= 0) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field refreshTokenLifetimeSeconds must be positive (> 0), got: %d", msg.getRefreshTokenLifetimeSeconds()));
}
// Validate fqdn (assert_fqdn)
if (!msg.getFqdn().isEmpty()) {
Validation.validateFQDN(msg.getFqdn(), "fqdn");
}
// Validate tlsCertLifetimeSeconds (assert_duration: POSITIVE)
if (msg.getTlsCertLifetimeSeconds() <= 0) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field tlsCertLifetimeSeconds must be positive (> 0), got: %d", msg.getTlsCertLifetimeSeconds()));
}
// Validate maxTokenLifetimeSeconds (assert_duration: POSITIVE)
if (msg.getMaxTokenLifetimeSeconds() <= 0) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field maxTokenLifetimeSeconds must be positive (> 0), got: %d", msg.getMaxTokenLifetimeSeconds()));
}
}
