public static Kernel.Delegate.Builder mergeDelegate(Kernel.Delegate dst, Kernel.Delegate src) {
Kernel.Delegate.Builder builder = dst.toBuilder();
if (dst.getName().isEmpty()) { builder.setName(src.getName()); }
if (dst.getCredPairsList().isEmpty()) { builder.addAllCredPairs(src.getCredPairsList()); }
if (dst.getCloudIdentitiesList().isEmpty()) { builder.addAllCloudIdentities(src.getCloudIdentitiesList()); }
if (dst.getAuthorizedServicesList().isEmpty()) { builder.addAllAuthorizedServices(src.getAuthorizedServicesList()); }
if (dst.getAuthorizedProfilesList().isEmpty()) { builder.addAllAuthorizedProfiles(src.getAuthorizedProfilesList()); }
if (dst.getCustomClaimsMap().isEmpty()) { builder.putAllCustomClaims(src.getCustomClaimsMap()); }
return builder;
}
public static Kernel.Config.Builder mergeConfig(Kernel.Config dst, Kernel.Config src) {
Kernel.Config.Builder builder = dst.toBuilder();
if (dst.getTrustedCasList().isEmpty()) { builder.addAllTrustedCas(src.getTrustedCasList()); }
if (!dst.hasRateLimit() && src.hasRateLimit()) { builder.setRateLimit(src.getRateLimit()); }
if (!dst.hasConfigs() && src.hasConfigs()) { builder.setConfigs(src.getConfigs()); }
if (dst.getKeyRotationIntervalSeconds() == 0) { builder.setKeyRotationIntervalSeconds(src.getKeyRotationIntervalSeconds()); }
if (dst.getDefaultTokenExpirySeconds() == 0) { builder.setDefaultTokenExpirySeconds(src.getDefaultTokenExpirySeconds()); }
if (dst.getDelegatesList().isEmpty()) { builder.addAllDelegates(src.getDelegatesList()); }
if (dst.getCaCertLifetimeSeconds() == 0) { builder.setCaCertLifetimeSeconds(src.getCaCertLifetimeSeconds()); }
if (dst.getEntitlementProfilesList().isEmpty()) { builder.addAllEntitlementProfiles(src.getEntitlementProfilesList()); }
if (dst.getAccessTokenLifetimeSeconds() == 0) { builder.setAccessTokenLifetimeSeconds(src.getAccessTokenLifetimeSeconds()); }
if (dst.getRefreshTokenLifetimeSeconds() == 0) { builder.setRefreshTokenLifetimeSeconds(src.getRefreshTokenLifetimeSeconds()); }
if (dst.getTrustDomain().isEmpty()) { builder.setTrustDomain(src.getTrustDomain()); }
if (dst.getFqdn().isEmpty()) { builder.setFqdn(src.getFqdn()); }
if (dst.getIssuer().isEmpty()) { builder.setIssuer(src.getIssuer()); }
if (dst.getTlsCertLifetimeSeconds() == 0) { builder.setTlsCertLifetimeSeconds(src.getTlsCertLifetimeSeconds()); }
if (dst.getMaxTokenLifetimeSeconds() == 0) { builder.setMaxTokenLifetimeSeconds(src.getMaxTokenLifetimeSeconds()); }
return builder;
}
