public static Kernel.Cluster.Builder mergeCluster(Kernel.Cluster dst, Kernel.Cluster src) {
Kernel.Cluster.Builder builder = dst.toBuilder();
if (!dst.hasClusterInfo() && src.hasClusterInfo()) { builder.setClusterInfo(src.getClusterInfo()); }
if (!dst.hasClusterHealth() && src.hasClusterHealth()) { builder.setClusterHealth(src.getClusterHealth()); }
if (dst.getNodeMetricsList().isEmpty()) { builder.addAllNodeMetrics(src.getNodeMetricsList()); }
if (dst.getGrpcStatsList().isEmpty()) { builder.addAllGrpcStats(src.getGrpcStatsList()); }
if (dst.getPersistenceStatusList().isEmpty()) { builder.addAllPersistenceStatus(src.getPersistenceStatusList()); }
if (dst.getNetworkStatsList().isEmpty()) { builder.addAllNetworkStats(src.getNetworkStatsList()); }
if (dst.getThreadInfoList().isEmpty()) { builder.addAllThreadInfo(src.getThreadInfoList()); }
if (dst.getTokenCacheStatsList().isEmpty()) { builder.addAllTokenCacheStats(src.getTokenCacheStatsList()); }
if (dst.getMapStatsList().isEmpty()) { builder.addAllMapStats(src.getMapStatsList()); }
if (!dst.hasSetLogLevel() && src.hasSetLogLevel()) { builder.setSetLogLevel(src.getSetLogLevel()); }
else if (dst.hasSetLogLevel() && src.hasSetLogLevel()) { builder.setSetLogLevel(mergeAdminSetLogLevelRequest(dst.getSetLogLevel(), src.getSetLogLevel()).build()); }
if (!dst.hasConfigDump() && src.hasConfigDump()) { builder.setConfigDump(src.getConfigDump()); }
else if (dst.hasConfigDump() && src.hasConfigDump()) { builder.setConfigDump(mergeAdminConfigDump(dst.getConfigDump(), src.getConfigDump()).build()); }
if (!dst.hasReloadConfig() && src.hasReloadConfig()) { builder.setReloadConfig(src.getReloadConfig()); }
else if (dst.hasReloadConfig() && src.hasReloadConfig()) { builder.setReloadConfig(mergeAdminReloadConfigRequest(dst.getReloadConfig(), src.getReloadConfig()).build()); }
if (!dst.hasBootstrapConfig() && src.hasBootstrapConfig()) { builder.setBootstrapConfig(src.getBootstrapConfig()); }
else if (dst.hasBootstrapConfig() && src.hasBootstrapConfig()) { builder.setBootstrapConfig(mergeBootstrapConfig(dst.getBootstrapConfig(), src.getBootstrapConfig()).build()); }
if (!dst.hasGrpcConfig() && src.hasGrpcConfig()) { builder.setGrpcConfig(src.getGrpcConfig()); }
else if (dst.hasGrpcConfig() && src.hasGrpcConfig()) { builder.setGrpcConfig(mergeConfig(dst.getGrpcConfig(), src.getGrpcConfig()).build()); }
if (dst.getGraphRegistryList().isEmpty()) { builder.addAllGraphRegistry(src.getGraphRegistryList()); }
if (dst.getServiceConnectionsList().isEmpty()) { builder.addAllServiceConnections(src.getServiceConnectionsList()); }
if (dst.getQueueStatsList().isEmpty()) { builder.addAllQueueStats(src.getQueueStatsList()); }
if (dst.getTopicStatsList().isEmpty()) { builder.addAllTopicStats(src.getTopicStatsList()); }
if (dst.getWatchHealthList().isEmpty()) { builder.addAllWatchHealth(src.getWatchHealthList()); }
if (dst.getMutationRatesList().isEmpty()) { builder.addAllMutationRates(src.getMutationRatesList()); }
return builder;
}
